TreeNode <T> parent = current.getParent();

if (parent == null) {
parent = current;
}

// Step 1: relink current node's right child to current node's left child
current.setRight(left.getLeft());

// Step 2: link current node's parent to current node's right child
parent.setLeft(right);

// Step 3: link right node's left child to current node
right.setLeft(node);

return right;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Get the left child of the node
    TreeNode<T> left = node.getLeft();

    // Set the node's left child to the left's right child
    node.setLeft(left.getRight());

    // Set the left's right child to the node
    left.setRight(node);

    // Return the left node as the new parent
    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
        // Check if the node is part of a tree
        if (node == null) {
            return null;
        }

        // Get the left child of the node
        TreeNode<T> left = node.getLeft();

        // If the left child is null, return the node
        if (left == null) {
            return node;
        }

        // Get the right child of the left child
        TreeNode<T> right = left.getRight();

        // Set the parent of the right child to the node
        left.setRight(node);

        // Set the left child of the node to the right child of the node
        node.setLeft(right);

        // Return the new parent of the node
        return left;
    }

