public String format(LoggingEvent event) {
    // Step 1: Extract the relevant information from the event
    String message = event.getMessage();
    Level level = event.getLevel();
    Date time = event.getTime();

    // Step 2: Apply the conversion pattern to generate the final output
    String output = "<" + level + ">" + time.toString() + ": " + message + "</" + level + ">";

    return output;
}

