public String format(LoggingEvent event) {
    // Step 1: Extract the relevant information from the event object
    String message = event.getMessage();
    Date date = event.getTimeStamp();
    String loggerName = event.getLoggerName();
    Level level = event.getLevel();
    String threadName = event.getThreadName();
    StackTraceElement[] stackTrace = event.getStackTrace();

    // Step 2: Create a format string using the conversion pattern
    String format = "*** %s *** - %s %s - %s %s %s";

    // Step 3: Replace the placeholders in the format string with the actual values
    message = String.format(format, date, level, loggerName, message, threadName, stackTrace);

    return message;
}

