    String message = event.getMessage();
    String stackTrace = (throwable != null) ? throwable.printStackTrace() : "";
    String errorMessage = (throwable != null) ? throwable.getMessage() : "";
    String formattedMessage = String.format("%s%s%s%s", message, stackTrace, errorMessage);
    return formattedMessage;
}

