    int index = headerPart.indexOf("\r\n", end);

    // If no \r\n sequence is found, return the length of the string
    if (index == -1) {
        return headerPart.length();
    }

    // Return the index of the \r\n sequence
    return index;
}

private int parseEndOfLine(String headerPart, int end) {
    // Find the end of the line by searching for the \r\n sequence
    int index = headerPart.indexOf("\r\n", end);

    // If the sequence was not found, throw an exception
    if (index == -1) {
        throw new IllegalArgumentException("End of line not found");
    }

    // Return the index of the \r\n sequence
    return index;
}

private int parseEndOfLine(String headerPart, int end) {
    // Check if end of line marker has been reached
    if (headerPart.charAt(end) == '\r' && headerPart.charAt(end + 1) == '\n') {
        // Return index of end of line marker
        return end + 1;
    }

    // Skip all characters until end of line marker is reached
    for (int i = end; i < headerPart.length(); i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i + 1;
        }
    }

    // If end of line marker was not found, return length of header part
    return headerPart.length();
}

private int parseEndOfLine(String headerPart, int end) {
    // Find the index of the \r\n sequence that marks the end of the line
    int endOfLineIndex = headerPart.indexOf("\r\n", end);

    // If the \r\n sequence was not found, return the length of the header part
    if (endOfLineIndex == -1) {
        return headerPart.length();
    }

    // Otherwise, return the index of the \r\n sequence
    return endOfLineIndex;
}

public static int parseEndOfLine(String headerPart, int end) {
    // Check if we have reached the end of the header
    if (end >= headerPart.length()) {
        throw new IllegalArgumentException("Reached end of header while parsing end of line");
    }

    // Look for the \r\n sequence, which indicates end of line
    int indexOfCR = headerPart.indexOf('\r', end);
    int indexOfLF = headerPart.indexOf('\n', end);
    int indexOfEndOfLine;
    if (indexOfCR != -1 && indexOfLF != -1) {
        // Check that the \r\n sequence is not escaped
        if (indexOfCR == indexOfLF - 1 && headerPart.charAt(indexOfCR - 1) == '\\') {
            // The \r\n sequence is escaped, so continue searching
            indexOfEndOfLine = parseEndOfLine(headerPart, indexOfLF + 1);
        } else {
            // The \r\n sequence is not escaped, so return the index of LF
            indexOfEndOfLine = indexOfLF;
        }
    } else if (indexOfCR != -1) {
        // Only \r found, so return the index of CR
        indexOfEndOfLine = indexOfCR;
    } else if (indexOfLF != -1) {
        // Only \n found, so return the index of LF
        indexOfEndOfLine = indexOfLF;
    } else {
        // No \r or \n found, so return the end of the header
        indexOfEndOfLine = end;
    }

    // Return the index of the \r\n sequence, which indicates end of line
    return indexOfEndOfLine;
}

