public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    // Check if the input graph is valid
    if (graph == null) {
        throw new IllegalArgumentException("Input graph cannot be null");
    }

    // Create a new mapping object
    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<>();

    // Loop through all vertices in the input graph
    for (V v : graph.getVertices()) {
        // Create a new set to represent the vertices in the output graph
        Set<V> vertices = new HashSet<>();
        // Add the current vertex to the set
        vertices.add(v);
        // Add the set to the mapping
        mapping.put(v, vertices);
    }

    // Loop through all edges in the input graph
    for (E e : graph.getEdges()) {
        // Get the source and target vertices of the current edge
        V sourceVertex = graph.getEdgeSource(e);
        V targetVertex = graph.getEdgeTarget(e);
        // Get the sets of vertices representing the source and target vertices in the output graph
        Set<V> sourceVertices = mapping.get(sourceVertex);
        Set<V> targetVertices = mapping.get(targetVertex);
        // Add the source and target vertices to the sets of vertices in the output graph
        sourceVertices.add(targetVertex);
        targetVertices.add(sourceVertex);
    }

    return mapping;
}

public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    // Create a new mapping from the input graph to itself
    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<V, E>(graph);

    // Iterate over the vertices in the input graph
    for (V vertex : graph.getVertices()) {
        // Add a self-loop mapping to the new mapping
        mapping.addMapping(vertex, vertex);
    }

    return mapping;
}

