    // Step 2: Create a queue to hold the vertices of the graph
    Queue<V> queue = new LinkedList<>();

    // Step 3: Add the vertices to the queue
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        queue.add(entry.getValue());
    }

    // Step 4: Create a set to hold the edges of the graph
    Set<E> edges = new HashSet<>();

    // Step 5: While the queue is not empty
    while (!queue.isEmpty()) {
        // Step 5.1: Dequeue a vertex from the queue
        V vertex = queue.remove();

        // Step 5.2: Find the neighbors of the vertex
        for (V neighbor : target.getNeighbors(vertex)) {
            // Step 5.2.1: If the neighbor is not in the result map, add it to the queue
            if (!resultMap.containsKey(neighbor.getLabel())) {
                queue.add(neighbor);
            }
            // Step 5.2.2: Add an edge between the vertex and the neighbor
            edges.add(new Edge<>(vertex, neighbor));
        }
    }

    // Step 6: Set the edges of the graph
    target.setEdges(edges);
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Step 1: Create the graph
    target.create();

    // Step 2: Add nodes to the graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        V node = entry.getValue();
        target.addNode(node);
    }

    // Step 3: Add edges to the graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
