public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Step 1: Validate the input
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }

    // Step 2: Convert the message to a byte array using the schema
    byte[] bytes = schema.toByteArray(message);

    // Step 3: Write the byte array to the output stream
    out.write(bytes.length);
    out.write(bytes, 0, bytes.length);

    return bytes.length;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {

        // Step 1: Calculate the size of the message
        int size = schema.calculateSize(message);
        buffer.clear();

        // Step 2: Write the size of the message
        writeInt(out, size);

        // Step 3: Reset the buffer
        buffer.clear();

        // Step 4: Write the message
        ProtoWriter writer = ProtoWriter.newInstance(buffer, schema);
        writer.writeMessage(message);

        // Step 5: Write the buffer
        writeBytes(out, buffer.asReadOnlyByteBuffer());

        // Step 6: Return the size of the message
        return size;
    }

public static int writeDelimitedTo(OutputStream out, Object message, Schema<?> schema, LinkedBuffer buffer) throws IOException {
    // Step 1: Serialize the message with the given schema and buffer
    byte[] serializedMessage = schema.serialize(message, buffer);

    // Step 2: Write the length of the message to the output stream
    int messageSize = serializedMessage.length;
    out.write(messageSize);

    // Step 3: Write the serialized message to the output stream
    out.write(serializedMessage);

    return messageSize;
}

