public int available() throws IOException {
    // Check if the input stream is closed
    if (isClosed()) {
        throw new IOException("Stream closed");
    }

    // Get the remaining number of bytes in the buffer
    int availableBytes = this.buffer.remaining();

    // If the remaining bytes are less than or equal to the buffer size, return the remaining bytes
    if (availableBytes <= this.bufferSize) {
        return availableBytes;
    }

    // Otherwise, check if the end of the stream has been reached
    if (this.stream.available() == 0) {
        // If the end of the stream has been reached, return 0
        return 0;
    }

    // Otherwise, return the buffer size
    return this.bufferSize;
}

