public Mappings diffStructure(String tableName, Mappings mappings) {
    // Create a GET request to fetch the mappings of the index
    Request request = new Request("GET", "/" + tableName + "/_mappings");
    try {
        // Execute the GET request and get the response
        var response = IndicesAdminClient.get().getMappings(request.get().build()));
        // Check if the request was successful
        if (response.isAcknowledged()) {
            // Get the mappings from the response
            var currentMappings = response.getMappings();
            // Iterate over the fields in the current mappings
            for (var field : currentMappings) {
                // Check if the field does not exist in the input mappings
                if (!mappings.contains(field)) {
                    // Add the field to the input mappings
                    mappings.add(field);
                }
            }
            // Return the merged mappings
            return mappings;
        } else {
            throw new Exception(String.format("Get mappings request failed for index %s", tableName));
        }
    } catch (IOException e) {
        throw new UncheckedIOException(String.format("Failed to get mappings for index %s", tableName), e);
    }
}

