public long readLong(int offset) {
    long value = 0L;
    int readBytes = 0;
    while (readBytes < 8) {
        int currentByte = readByte(offset + readBytes);
        value |= ((long) currentByte & 0xFF) << (8 * readBytes);
        readBytes++;
    }
    return value;
}

public long readLong(final int offset) throws IOException {
    // Check if the offset is valid
    if (offset < 0 || offset > this.buf.length - 8) {
        throw new IOException("Invalid offset " + offset + " for ClassReader readLong");
    }

    long value = 0;
    value |= (this.buf[offset] & 0xFF) << 56;
    value |= (this.buf[offset + 1] & 0xFF) << 48;
    value |= (this.buf[offset + 2] & 0xFF) << 40;
    value |= (this.buf[offset + 3] & 0xFF) << 32;
    value |= (this.buf[offset + 4] & 0xFF) << 24;
    value |= (this.buf[offset + 5] & 0xFF) << 16;
    value |= (this.buf[offset + 6] & 0xFF) << 8;
    value |= (this.buf[offset + 7] & 0xFF);
    return value;
}

