public List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd + 1;
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd + 1;
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Check that the start and end times are valid
    if (start < 0 || end < 0) {
        throw new IllegalArgumentException("Start and end times must be non-negative");
    }

    // Check that the start time is less than the end time
    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than end time");
    }

    // Calculate the time range duration
    long duration = end - start;

    // Check that the duration is less than the allowed fetch data duration
    if (duration > FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("Duration must be less than fetch data duration");
    }

    // Split the time range into sub-ranges
    List<TimeRange> timeRanges = new ArrayList<>();
    for (long i = 0; i < duration; i += SUB_RANGE_DURATION) {
        long startTime = start + i;
        long endTime = startTime + SUB_RANGE_DURATION;
        if (endTime > end) {
            endTime = end;
        }
        timeRanges.add(new TimeRange(startTime, endTime));
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long fetchDataDuration = FETCH_DATA_DURATION;
    long timeRangeDuration = fetchDataDuration / 4;

    long startTime = Math.max(start, fetchDataDuration);
    long endTime = Math.min(end, fetchDataDuration * 5);

    while (startTime < endTime) {
        long timeRangeStart = startTime;
        long timeRangeEnd = Math.min(timeRangeStart + timeRangeDuration, endTime);

        TimeRange timeRange = new TimeRange(timeRangeStart, timeRangeEnd);
        timeRanges.add(timeRange);

        startTime = timeRangeEnd + 1;
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    long duration = Math.min(end - start, FETCH_DATA_DURATION);
    long startTime = start;

    while (startTime < end) {
        long endTime = Math.min(startTime + duration, end);
        timeRanges.add(new TimeRange(startTime, endTime));
        startTime = endTime + 1;
    }

    return timeRanges;
}

