public static long compressTimeBucket(long timeBucket, int dayStep){
        long year = timeBucket / 100000000000000L % 10000;
        long month = timeBucket / 100000000000L % 10000;
        long day = timeBucket / 1000000L % 1000000;
        long hour = timeBucket / 10000L % 10000;
        long minute = timeBucket / 100L % 10000;
        long second = timeBucket % 100;

        // re-format time bucket
        long newTimeBucket = 0;
        newTimeBucket = newTimeBucket * 100000000000000L + year * 100000000000L + month * 1000000L + day;
        newTimeBucket = newTimeBucket * 10000L + hour * 10000L + minute * 100L + second * 100L + dayStep;

        return newTimeBucket;
    }

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Check if the input is valid
    if (timeBucket < 0 || dayStep < 0) {
        throw new IllegalArgumentException("Invalid input: timeBucket and dayStep must be non-negative");
    }

    // Get the year, month, and day from the time bucket
    int year = (int) (timeBucket / 1000000);
    int month = (int) ((timeBucket % 1000000) / 10000);
    int day = (int) (timeBucket % 10000);

    // Calculate the new day of the month
    int newDay = day - dayStep;
    if (newDay < 1) {
        newDay += 31;
    }

    // Calculate the new month and year
    int newMonth = month;
    int newYear = year;
    if (newDay <= 31) {
        // Do nothing
    } else if (newDay <= 61) {
        newMonth++;
        newDay -= 31;
    } else if (newDay <= 92) {
        newMonth += 2;
        newDay -= 61;
    } else if (newDay <= 122) {
        newYear++;
        newMonth += 2;
        newDay -= 92;
    } else if (newDay <= 153) {
        newYear++;
        newMonth++;
        newDay -= 122;
    } else if (newDay <= 184) {
        newYear += 2;
        newMonth++;
        newDay -= 153;
    } else if (newDay <= 214) {
        newYear += 3;
        newMonth++;
        newDay -= 184;
    } else if (newDay <= 245) {
        newYear += 4;
        newMonth++;
        newDay -= 214;
    } else if (newDay <= 275) {
        newYear += 5;
        newMonth++;
        newDay -= 245;
    } else if (newDay <= 306) {
        newYear += 6;
        newMonth++;
        newDay -= 275;
    } else if (newDay <= 337) {
        newYear += 7;
        newMonth++;
        newDay -= 306;
    } else if (newDay <= 366) {
        newYear += 8;
        newMonth++;
        newDay -= 337;
    } else {
        throw new IllegalArgumentException("Invalid dayStep: " + dayStep);
    }

    // Return the new time bucket
    return (long) (newYear * 1000000 + newMonth * 10000 + newDay);
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the day component of the time bucket
    int day = (int) (timeBucket / 10000);

    // Calculate the time component of the time bucket
    int time = (int) (timeBucket % 10000);

    // Calculate the new day component based on the day step
    int newDay = day - (day % dayStep);

    // Return the new time bucket
    return newDay * 10000 + time;
}

long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the day number in the current time bucket
    int day = (int)(timeBucket / (24 * 60 * 60));
    // Calculate the final day number after applying the dayStep
    int finalDay = day + dayStep;
    // Calculate the final time bucket from the final day number
    long finalTimeBucket = finalDay * (24 * 60 * 60);
    // Return the final time bucket
    return finalTimeBucket;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the re-formatted time bucket
    long reFormattedTimeBucket = timeBucket - timeBucket % dayStep + 1;

    // If the re-formatted time bucket is earlier than the input time bucket, it means the input time bucket is already in the previous day, so we need to add one day to the re-formatted time bucket
    if (reFormattedTimeBucket < timeBucket) {
        reFormattedTimeBucket += dayStep;
    }

    return reFormattedTimeBucket;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;

