        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            i++;
            size += 4;
        } else {
            size += 3;
        }
    }

    return size;
}

