    if (index < 0 || index >= strLength || len < 0 || len > strLength - index || index + len < 0 || index + len > strLength) {
        throw new IllegalArgumentException("Index and/or length is out of bounds");
    }
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
