public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Check for null inputs
    if (str == null || session == null || lb == null) {
      throw new NullPointerException("Inputs cannot be null");
    }

    // Get the length of the string and the length of the buffer
    int strLength = str.length();
    int bufferLength = lb.getBufferLength();

    // Check if there is enough space in the buffer for the string
    if (bufferLength - lb.getWriterIndex() < strLength) {
      // Not enough space, resize the buffer
      lb.resizeBuffer(bufferLength * 2);
    }

    // Get the writer index and the buffer's backing byte array
    int writerIndex = lb.getWriterIndex();
    byte[] buffer = lb.getBuffer();

    // Write the string to the buffer
    for (int i = 0; i < strLength; i++) {
      char c = str.charAt(i);
      if (c <= 0x007F) {
        buffer[writerIndex++] = (byte) c;
      } else if (c <= 0x07FF) {
        buffer[writerIndex++] = (byte) (0xC0 | c >> 6);
        buffer[writerIndex++] = (byte) (0x80 | c & 0x3F);
      } else {
        buffer[writerIndex++] = (byte) (0xE0 | c >> 12);
        buffer[writerIndex++] = (byte) (0x80 | c >> 6 & 0x3F);
        buffer[writerIndex++] = (byte) (0x80 | c & 0x3F);
      }
    }

    // Update the writer index
    lb.setWriterIndex(writerIndex);

    return lb;
  }

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {

    // Step 1: Validate the input parameters
    if (str == null) {
        throw new IllegalArgumentException("str cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("session cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("lb cannot be null");
    }

    // Step 2: Calculate the length of the UTF-8 encoding
    int utf8Length = -1;
    for (int i = 0; i < str.length(); i++) {
        int c = str.charAt(i);
        if (c < 0x80) {
            utf8Length++;
        } else if (c < 0x800) {
            utf8Length += 2;
        } else if (c < 0xd800 || c >= 0xe000) {
            utf8Length += 3;
        } else {
            // surrogate pair
            utf8Length += 4;
        }
    }

    // Step 3: Allocate space in the buffer for the UTF-8 bytes
    lb.ensureCapacity(utf8Length);

    // Step 4: Write the UTF-8 bytes to the buffer
    int bytesWritten = 0;
    for (int i = 0; i < str.length(); i++) {
        int c = str.charAt(i);
        if (c < 0x80) {
            lb.writeByte((byte) c);
        } else if (c < 0x800) {
            lb.writeByte((byte) (0xc0 | (c >> 6)));
            lb.writeByte((byte) (0x80 | (c & 0x3f)));
        } else if (c < 0xd800 || c >= 0xe000) {
            lb.writeByte((byte) (0xe0 | (c >> 12)));
            lb.writeByte((byte) (0x80 | ((c >> 6) & 0x3f)));
            lb.writeByte((byte) (0x80 | (c & 0x3f)));
        } else {
            // surrogate pair
            int u = str.charAt(i++);
            int uu = (((c & 0x3ff) << 10) | (u & 0x3ff)) + 0x10000;
            lb.writeByte((byte) (0xf0 | (uu >> 18)));
            lb.writeByte((byte) (0x80 | ((uu >> 12) & 0x3f)));
            lb.writeByte((byte) (0x80 | ((uu >> 6) & 0x3f)));
            lb.writeByte((byte) (0x80 | (uu & 0x3f)));
        }
        bytesWritten++;
    }

    // Step 5: Return the LinkedBuffer
    return lb;
}

