public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Calculate the length of the UTF-8 bytes for the input string
    int utf8Length = str.length();
    for (int i = 0; i < str.length(); i++) {
        utf8Length += str.get(i) > 0xFF;
    }

    // Write the UTF-8 bytes to the link buffer
    lb.writeByte(utf8Length);
    for (int i = 0; i < str.length(); i++) {
        int charByte = str.get(i);
        if (charByte > 0xFF) {
            lb.writeBytes(charByte, 2);
        } else {
            lb.writeByte(charByte);
        }
    }

    return lb;
}

