public void removeFromTreeEdgeList() {
    // The TreeEdge list without this edge
    TreeEdge newTreeEdgeListHead = null;
    // The TreeEdge list without this edge
    TreeEdge newTreeEdgeListTail = null;
    // The TreeEdge before this edge
    TreeEdge prevTreeEdge = null;
    // The TreeEdge after this edge
    TreeEdge nextTreeEdge = null;

    // If the tree edge list is empty
    if (treeEdgeListHead == null) {
        return;
    }

    // If the tree edge list has only one element
    if (treeEdgeListHead == this) {
        newTreeEdgeListHead = null;
        newTreeEdgeListTail = null;
    } else {
        // Find the previous and next edges in the tree edge list
        for (TreeEdge currentTreeEdge = treeEdgeListHead; currentTreeEdge != this; currentTreeEdge = currentTreeEdge.nextTreeEdge) {
            if (currentTreeEdge == null) {
                break;
            }
            prevTreeEdge = currentTreeEdge;
            nextTreeEdge = currentTreeEdge.nextTreeEdge;
        }

        // If previous edge is null, then this edge is the head of the list
        if (prevTreeEdge == null) {
            newTreeEdgeListHead = nextTreeEdge;
        } else {
            prevTreeEdge.nextTreeEdge = nextTreeEdge;
        }

        // If next edge is null, then this edge is the tail of the list
        if (nextTreeEdge == null) {
            newTreeEdgeListTail = prevTreeEdge;
        } else {
            nextTreeEdge.prevTreeEdge = prevTreeEdge;
        }
    }

    // Update the tree edge list head and tail
    treeEdgeListHead = newTreeEdgeListHead;
    treeEdgeListTail = newTreeEdgeListTail;

    // Remove the edge from the tree
    tree.removeEdge(this);
