    setNextEdge(null);
    setPreviousEdge(null);
}

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    return substituteVariables(value, props);
}

public static String findAndSubst(String key, Properties props) {
    // Check if the key is present in the properties file
    if (!props.containsKey(key)) {
        throw new IllegalArgumentException("Key not found");
    }

    // Get the value corresponding to the key
    String value = props.getProperty(key);

    // Perform variable substitution on the value
    Matcher matcher = Pattern.compile("\\$\\{([^}]+)\\}").matcher(value);
    StringBuffer sb = new StringBuffer();
    while (matcher.find()) {
        String replacement = System.getenv(matcher.group(1));
        if (replacement != null) {
            matcher.appendReplacement(sb, replacement);
        } else {
            throw new IllegalArgumentException("Environment variable not found");
        }
    }
    matcher.appendTail(sb);

    return sb.toString();
}

public static String findAndSubst(String key,Properties props) {
    // Check if the key is present in the properties file
    if (props.containsKey(key)) {
        // Get the value corresponding to the key
        String value = props.getProperty(key);

        // Perform variable substitution on the value
        // This will replace any occurrence of ${var} with the corresponding value of var in the same properties file
        value = value.replaceAll("\\$\\{(\\w+)\\}", match -> {
            // Check if the variable is defined in the properties file
            if (props.containsKey(match.group(1))) {
                // Return the value of the variable
                return props.getProperty(match.group(1));
            } else {
                // If the variable is not defined, return an empty string
                return "";
            }
        });

        return value;
    } else {
        // If the key is not present in the properties file, return an empty string
        return "";
    }
}

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    return value.replaceAll("\\$\\{(\\w+)\\}", (Matcher m) -> {
        String replacement = props.getProperty(m.group(1));
        if (replacement == null) {
            return "${" + m.group(1) + "}";
        } else {
            return replacement;
        }
    });
}

