    // Check if a Converter is registered for the specified class
    if (converters.containsKey(clazz)) {
        return converters.get(clazz);
    }

    // If no Converter is registered, try to find a rank-inferring Converter
    for (Map.Entry<Class, Converter> entry : converters.entrySet()) {
        // If the Converter is a rank-inferring Converter and can convert from the specified class, return it
        if (entry.getValue() instanceof RankInferringConverter && entry.getKey().isAssignableFrom(clazz)) {
            return entry.getValue();
        }
    }

    // If no Converter is found, return null
    return null;
}

