@Override
public Converter lookup(Class<?> clazz) {
    // Check if the registry contains a converter for the specified class
    Converter converter = converterRegistry.getConverter(clazz);
    if (converter != null) {
        return converter;
    }

    // If no converter was found, check if the class is an interface
    // and if it has a single implemented interface or superclass
    if (clazz.isInterface()) {
        Class<?>[] interfaces = clazz.getInterfaces();
        if (interfaces.length == 1) {
            return lookup(interfaces[0]);
        }
    } else {
        Class<?> superclass = clazz.getSuperclass();
        if (superclass != null) {
            return lookup(superclass);
        }
    }

    // If no converter was found for the class or its interfaces or superclass,
    // return null
    return null;
}

public Converter lookup(final Class<?> clazz) {
    // Validate input
    if (clazz == null) {
        throw new IllegalArgumentException("Clazz cannot be null");
    }

    // Look up the Converter for the specified class
    for (Converter converter : converters) {
        if (converter.getTargetClass().equals(clazz)) {
            return converter;
        }
    }

    // Return null if no registered Converter found
    return null;
}

