private void pop(final String descriptor) {
    // Check if the descriptor is a valid type descriptor
    if (!descriptor.startsWith("(") || !descriptor.endsWith(")")) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }

    // Get the number of argument types in the descriptor
    int numArguments = descriptor.length() - 2;

    // Create an array to store the popped argument types
    Class<?>[] poppedArguments = new Class<?>[numArguments];

    // Pop each argument type from the output frame stack
    for (int i = numArguments - 1; i >= 0; i--) {
        String argumentType = descriptor.substring(i + 1, i + 2);
        poppedArguments[i] = popArgumentType(argumentType);
    }

    // Return the popped argument types as an array
    return poppedArguments;
}

void pop(String descriptor) {
    // Make sure the descriptor is not null
    if (descriptor == null) {
        throw new IllegalArgumentException("Desriptor cannot be null");
    }

    // If the descriptor is a type descriptor, pop only one value
    if (descriptor.charAt(0) == 'L') {
        outputFrame.pop();
    }

    // If the descriptor is a method descriptor, pop only the argument values
    if (descriptor.charAt(0) == '(') {
        final String[] argumentTypes = descriptor.substring(1, descriptor.indexOf(')'));
        for (final String type : argumentTypes) {
            if (type.charAt(0) == 'L') {
                outputFrame.pop();
            }
        }
    }
}

private void pop(final String descriptor) {
    // Check for invalid descriptor
    if (descriptor == null) {
        throw new IllegalArgumentException("Illegal descriptor: null");
    }

    // Parse descriptor and determine the number of stack elements to pop
    int numElementsToPop = 0;
    String[] splitDescriptor = descriptor.split(";");
    for (String element : splitDescriptor) {
        // Handle arrays
        if (element.startsWith("[")) {
            numElementsToPop += Integer.parseInt(element.substring(1));
        } else {
            // Handle non-array types
            numElementsToPop++;
        }
    }

    // Pop the specified number of stack elements
    for (int i = 0; i < numElementsToPop; i++) {
        outputFrame.pop();
    }
}

private void pop(final String descriptor) {
    if (descriptor.contains("(")) {
        // extract the argument types from the descriptor
        String[] args = descriptor.substring(1, descriptor.length() - 1).split(";");
        // loop through the argument types and pop them from the output frame stack
        for (String arg : args) {
            frame.pop(arg);
        }
    } else {
        // there are no argument types, so just pop a single abstract type
        frame.pop(descriptor);
    }
}

public void pop(String descriptor) {
    // Calculate the number of abstract types to pop based on the descriptor
    int numAbstractTypesToPop = 0;
    if (descriptor.charAt(0) == '(') {
        numAbstractTypesToPop = calculateNumArgumentTypes(descriptor);
    } else {
        numAbstractTypesToPop = 1;
    }

    // Pop the required number of abstract types from the output frame stack
    for (int i = 0; i < numAbstractTypesToPop; i++) {
        outputFrame.pop();
    }
}

