protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Check if the edge is already in the index
    if (!containsEdge(e)) {
        // Add the edge to the index
        index.put(sourceVertex, targetVertex, e);
        // Add the vertices to the index
        index.put(sourceVertex, e);
        index.put(targetVertex, e);
    } else {
        // The edge is already in the index, throw an exception
        throw new RuntimeException("The edge is already in the index");
    }
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Step 1: Check if the edge already exists in the index
    if (index.containsKey(sourceVertex) && index.get(sourceVertex).containsKey(targetVertex)) {
        // If the edge already exists, we don't need to add it again
        return;
    }

    // Step 2: Add the edge to the index
    if (!index.containsKey(sourceVertex)) {
        // If the source vertex is not in the index, we need to add it
        index.put(sourceVertex, new HashMap<>());
    }
    index.get(sourceVertex).put(targetVertex, e);

    // Step 3: Add the inverse edge to the index
    if (!index.containsKey(targetVertex)) {
        // If the target vertex is not in the index, we need to add it
        index.put(targetVertex, new HashMap<>());
    }
    index.get(targetVertex).put(sourceVertex, e);
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Check if the edge already exists
    if (index.containsKey(sourceVertex) && index.get(sourceVertex).contains(e)) {
        // If the edge already exists, return
        return;
    }

    // Add the edge to the index
    if (!index.containsKey(sourceVertex)) {
        index.put(sourceVertex, new HashSet<>());
    }
    index.get(sourceVertex).add(e);

    // Add the edge to the index
    if (!index.containsKey(targetVertex)) {
        index.put(targetVertex, new HashSet<>());
    }
    index.get(targetVertex).add(e);
}

