protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Check for invalid input
    if (sourceVertex == null || targetVertex == null || e == null) {
        throw new IllegalArgumentException("Null input not allowed");
    }

    // Add the edge to the appropriate index
    Map<V, List<E>> edgeMap = getEdgeMap(sourceVertex);
    if (edgeMap == null) {
        edgeMap = new HashMap<>();
    }
    List<E> edges = edgeMap.get(targetVertex);
    if (edges == null) {
        edges = new ArrayList<>();
    }
    edges.add(e);
    edgeMap.put(targetVertex, edges);

    // Add the index to the index map
    Map<V, Map<V, List<E>>> indexMap = getIndexMap();
    indexMap.put(sourceVertex, edgeMap);
}

public static File[] getClassPath() {
    // Get the system class loader
    ClassLoader classLoader = ClassLoader.getSystemClassLoader();

    // Get the URL class path of the current class loader
    URL[] urls = classLoader.getURLs();

    // Convert the URL array to a File array
    File[] files = new File[urls.length];
    for (int i = 0; i < urls.length; i++) {
        files[i] = new File(urls[i].getPath());
    }

    return files;
}

public static File[] classPath() {
    // Retrieve the class path of the current JVM instance as an array of File objects
    return (File[]) AccessController.doPrivileged(new PrivilegedAction<Object>() {
        @Override
        public Object run() {
            return System.getProperty("java.class.path");
        }
    });
}

private static File[] classPath() {
    return ClassLoader.getSystemClassLoader().getURLs().stream().map(u -> new File(u.getFile())).toArray(File[]::new);
}

private static File[] classPath() {
        // Get the list of URLs for the classpath
        URL[] classPathUrls = sun.misc.Launcher.getBootClassPath().getURLs();

        // Construct a list of File objects for each URL
        List<File> classPath = new ArrayList<>();
        for (URL url : classPathUrls) {
            try {
                classPath.add(new File(url.toURI()));
            } catch (URISyntaxException e) {
                // Ignore invalid URLs
            }
        }

        // Convert the list to an array
        return classPath.toArray(new File[0]);
    }

public static File[] classPath() {
    // Get the current JVM instance
    RuntimeMXBean runtime = ManagementFactory.getRuntimeMXBean();

    // Get the class path of the JVM as a list of strings
    List<String> classPathList = runtime.getClassPath();

    // Convert the class path to an array of File objects
    File[] classPath = new File[classPathList.size()];
    for (int i = 0; i < classPathList.size(); i++) {
        classPath[i] = new File(classPathList.get(i));
    }

    return classPath;
}

