public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the x-coordinate of the center of the box
    double centerX = box.getMinX() + (box.getMaxX() - box.getMinX()) / 2;

    // Split the box along the x-axis at the center x-coordinate
    Box2D leftBox = new Box2D(box.getMinX(), box.getMinY(), centerX, box.getMaxY());
    Box2D rightBox = new Box2D(centerX, box.getMinY(), box.getMaxX(), box.getMaxY());

    // Return a pair with the two resulting boxes
    return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the center of the box along the x axis
    double centerX = (box.getMinX() + box.getMaxX()) / 2;

    // Create two new boxes with the center of the current box as their center
    Box2D box1 = new Box2D(centerX, box.getMinY(), box.getMaxY());
    Box2D box2 = new Box2D(centerX, box.getMinY(), box.getMaxY());

    // Return a pair with the two resulting boxes
    return new Pair<>(box1, box2);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the x coordinate of the center of the box
    float centerX = box.getX() + box.getWidth() / 2.0f;

    // Calculate the width of the left and right boxes
    float leftWidth = centerX - box.getX();
    float rightWidth = box.getX() + box.getWidth() - centerX;

    // Create the left and right boxes
    Box2D leftBox = new Box2D(box.getX(), box.getY(), leftWidth, box.getHeight());
    Box2D rightBox = new Box2D(centerX, box.getY(), rightWidth, box.getHeight());

    // Return the pair of boxes
    return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Check if the box is already evenly divisible by 2 in the x direction
    if ((box.getWidth() & 1) == 0) {
        // The box is already evenly divisible, return a pair with the original box and an empty box
        return new Pair<>(box, new Box2D());
    }

    // Compute the x coordinate of the new center for the split box
    int centerX = box.getCenter().x();

    // Compute the width of the new box
    int newWidth = box.getWidth() / 2;

    // Compute the x coordinate of the upper left corner of the new box
    int newX = centerX - newWidth / 2;

    // Create a new box with the new dimensions
    Box2D newBox = new Box2D(newX, box.getY(), newWidth, box.getHeight());

    // Return a pair with the original box and the new box
    return new Pair<>(box, newBox);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {

    // Calculate the center of the box along the x-axis
    double centerX = box.getLeft() + (box.getWidth() / 2.0);

    // Calculate the half-width of the box
    double halfWidth = box.getWidth() / 2.0;

    // Create two new boxes
    Box2D leftBox = new Box2D(box.getTop(), box.getBottom(), centerX - halfWidth, box.getHeight());
    Box2D rightBox = new Box2D(box.getTop(), box.getBottom(), centerX + halfWidth, box.getHeight());

    // Return a pair with the two resulting boxes
    return new Pair<Box2D, Box2D>(leftBox, rightBox);
}

private void enlarge(int size) {
    // Check if the new size is valid
    if (size < 0) {
        throw new IllegalArgumentException("Size must be a positive integer");
    }
    // Calculate the new capacity
    int newCapacity = this.capacity + size;
    // Create a new array with the new capacity
    byte[] newArray = new byte[newCapacity];
    // Copy the contents of this.array to the new array
    System.arraycopy(this.array, 0, newArray, 0, this.array.length);
    // Update the fields in this object
    this.array = newArray;
    this.capacity = newCapacity;
}

