    final int newCapacity = data.length + size;

    // Create a new byte array with the new capacity
    byte[] newData = new byte[newCapacity];

    // Copy the existing bytes from the current byte vector to the new array
    System.arraycopy(data, 0, newData, 0, data.length);

    // Update the reference to the data array with the new byte array
    data = newData;
