public static String decapitalize(String name) {
    char[] chars = name.toCharArray();
    boolean capitalizeNext = true;
    for (int i = 0; i < chars.length; i++) {
        if (capitalizeNext) {
            chars[i] = Character.toLowerCase(chars[i]);
            capitalizeNext = false;
        } else if (Character.isWhitespace(chars[i])) {
            capitalizeNext = true;
        }
    }
    return new String(chars);
}

public static String decapitalize(String name){
int length = name.length();
if (length == 0) {
return name;
}
char[] nameChars = name.toCharArray();
char firstChar = nameChars[0];
boolean hasSpace = false;
for (int i = 0; i < length; i++) {
char c = nameChars[i];
if (Character.isSpaceChar(c)) {
hasSpace = true;
continue;
}
if (!Character.isUpperCase(c)) {
break;
}
}
if (!hasSpace && Character.isLowerCase(nameChars[1])) {
return name;
}
char[] decapitalizedNameChars = new char[length];
for (int i = 0; i < length; i++) {
if (Character.isSpaceChar(nameChars[i])) {
decapitalizedNameChars[i] = nameChars[i];
} else {
decapitalizedNameChars[i] = Character.toLowerCase(nameChars[i]);
}
}
return decapitalizedNameChars;
}
