public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {

    // Validate input
    if (out == null) {
        throw new IllegalArgumentException("DataOutput cannot be null");
    }
    if (node == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    // Write content size
    int contentSize = 0;
    out.writeInt(contentSize);

    // Write buffer content
    for (byte[] bytes : node.getNode()) {
        out.write(bytes);
        contentSize += bytes.length;
    }

    return contentSize;
}

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        // Write the current node's value
        out.writeInt(node.getValue());
        // Increment the total size
        totalSize += 4;
        // Move to the next node
        node = node.getNext();
    }
    return totalSize;
}

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    int totalBytes = 0;

    // Iterate through the nodes in the linked buffer
    for (Node<Object> currentNode = node; currentNode != null; currentNode = currentNode.tail) {
        // Write the value and size of the current node
        out.writeInt(currentNode.value.length);
        out.write(currentNode.value);

        // Increment the total bytes written
        totalBytes += currentNode.value.length;
    }

    return totalBytes;
}

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null");
    }
    if (out == null) {
        throw new IllegalArgumentException("Data output cannot be null");
    }

    int totalSize = 0;
    while (node != null) {
        out.writeByte(node.getByte());
        totalSize++;
        node = node.getNext();
    }
    return totalSize;
}

int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    // Check for null inputs
    if (out == null || node == null) {
        throw new NullPointerException("null inputs are not allowed");
    }

    // Write the content of the buffer to the output
    int totalSize = 0;
    for (Object obj : node) {
        out.writeObject(obj);
        totalSize += 4; // 4 bytes for each object written
    }

    return totalSize;
}

