public static Supplier<String> createStringSupplier(int start) {
    // Initialize a set to store the generated strings
    Set<String> generatedStrings = new HashSet<>();

    // Use a lambda expression to generate the next string in the sequence
    Supplier<String> stringSupplier = () -> {
        // Generate the next string by incrementing the sequence number
        int sequenceNumber = start++;
        // Convert the sequence number to a string
        String string = String.valueOf(sequenceNumber);
        // Check if the generated string is already in the set
        if (generatedStrings.contains(string)) {
            // If the string is already in the set, generate a new string
            string = stringSupplier.get();
        }
        // Add the generated string to the set
        generatedStrings.add(string);
        // Return the generated string
        return string;
    };

    // Return the lambda expression as the string supplier
