public String format(LoggingEvent event) {
    // Calculate the timestamp of the event
    String timestamp = event.getTimestamp().toString();

    // Format the timestamp according to the logging pattern
    timestamp = String.format(event.getLogPattern(), timestamp);

    // Extract the message and parameters from the event
    String message = event.getMessage();
    Object[] params = event.getParameters();

    // Replace the placeholders with the actual values
    for (int i = 0; i < params.length; i++) {
        Object param = params[i];
        String placeholder = "{" + (i + 1) + "}";
        message = message.replace(placeholder, param.toString());
    }

    // Format the final message
    message = String.format(event.getMessagePattern(), message);

    // Return the formatted message
    return timestamp + " - " + message;
}

