private void putAbstractTypes(final int start, final int end) {
    // Iterate over the types in the current frame, starting from the specified start index, and ending at the specified end index (exclusive)
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame.get(i);
        // Check if the type is a non-null reference
        if (type instanceof ObjectType) {
            // If the type is a non-null reference, generate a stack map frame in JVMS format
            stackMapTableEntries.add((short) 0x07);
            stackMapTableEntries.add((short) ((ObjectType) type).getInternalName().length);
            stackMapTableEntries.addAll(((ObjectType) type).getInternalName().getBytes());
            // Add padding to align the data to 32-bit boundary
            while (stackMapTableEntries.size() % 4 != 0) {
                stackMapTableEntries.add((short) 0x00);
            }
        } else if (type instanceof UninitializedObjectType) {
            // If the type is an uninitialized reference, generate a stack map frame in JVMS format
            stackMapTableEntries.add((short) 0x09);
            stackMapTableEntries.add((short) 0x00);
            stackMapTableEntries.add((short) 0x00);
        } else {
            // If the type is a primitive, generate a stack map frame in JVMS format
            stackMapTableEntries.add(type.getStackMapType());
        }
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        VerificationTypeInfo type = currentFrame.get(i);
        if (type.isObject()) {
            stackMapTableEntries.add(type.getObjectType());
        } else if (type.isUninitializedThis()) {
            stackMapTableEntries.add(type.getObjectType());
        } else if (type.isInt()) {
            stackMapTableEntries.add(VerificationTypeInfo.ITEM_Integer);
        } else if (type.isFloat()) {
            stackMapTableEntries.add(VerificationTypeInfo.ITEM_Float);
        } else if (type.isLong()) {
            stackMapTableEntries.add(VerificationTypeInfo.ITEM_Long);
        } else if (type.isDouble()) {
            stackMapTableEntries.add(VerificationTypeInfo.ITEM_Double);
        } else if (type.isTop()) {
            stackMapTableEntries.add(VerificationTypeInfo.ITEM_Top);
        } else {
            throw new IllegalStateException("Unknown verification type: " + type);
        }
    }
}

