public Character convertToType(Class<?> type, Object value) throws Exception {
    // Check if the input value is a character
    if (value instanceof Character) {
        return (Character) value;
    }

    // Check if the input value is a string
    if (value instanceof String) {
        String input = (String) value;
        if (input.length() == 1) {
            return input.charAt(0);
        }
    }

    // Check if the input value is a number
    if (value instanceof Number) {
        int input = ((Number) value).intValue();
        if (input >= Character.MIN_VALUE && input <= Character.MAX_VALUE) {
            return (char) input;
        }
    }

    // If none of the above conditions are met, throw an exception
    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

private Character convertToCharacter(final Class<?> type, final Object value) throws Exception {
    if (!Character.class.isAssignableFrom(type)) {
        throw new IllegalArgumentException("Cannot convert to " + type.getName() + " from character");
    }

    if (value == null) {
        return null;
    }

    if (value instanceof Character) {
        return (Character)value;
    }

    if (value instanceof String) {
        String strValue = (String)value;
        if (strValue.length() == 1) {
            return strValue.charAt(0);
        } else {
            throw new IllegalArgumentException("Cannot convert string value '" + strValue + "' to character");
        }
    }

    throw new IllegalArgumentException("Cannot convert value of type '" + value.getClass().getName() + "' to character");
}

