public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("desiredCapacity must be non-negative");
    }

    // Find the next prime number that is greater than or equal to desiredCapacity
    int prime = 2;
    while (prime < desiredCapacity) {
        prime++;
        if (isPrime(prime)) {
            return prime;
        }
    }

    // If the desired capacity is at least 1000, allow for 11% growth
    if (desiredCapacity >= 1000) {
        double growthFactor = 1.11;
        double desiredCapacityDbl = (double) desiredCapacity;
        double growth = growthFactor * desiredCapacityDbl;
        return (int) Math.round(growth);
    } else {
        return desiredCapacity;
    }
}

private static int nextPrime(int desiredCapacity) {
   // Check if the input is valid
   if (desiredCapacity <= 0) {
      throw new IllegalArgumentException("The desired capacity must be a positive integer.");
   }

   // Initialize the lower and upper bounds
   int lowerBound = 1;
   int upperBound = desiredCapacity;

   // Find the closest prime number to the desired capacity
   while (lowerBound < upperBound) {
      int mid = (lowerBound + upperBound) / 2;
      if (isPrime(mid)) {
         // If the mid point is prime, return it if it is greater than or equal to the desired capacity
         if (mid >= desiredCapacity) {
            return mid;
         }
         // If the mid point is not prime, update the lower bound
         else {
            lowerBound = mid + 1;
         }
      } else {
         // If the mid point is not prime, update the upper bound
         upperBound = mid - 1;
      }
   }

   // If no prime number is found between the lower and upper bounds, return the upper bound
   return upperBound;
}

public static int nextPrime(int desiredCapacity) {
    // Check if the desired capacity is negative or 0
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("Desired capacity must be a positive integer");
    }

    // Initialize the next prime variable
    int nextPrime = 1;

    // Loop through the numbers from 2 to the desired capacity
    for (int i = 2; i <= desiredCapacity; i++) {
        // Check if the number is prime
        boolean isPrime = true;
        for (int j = 2; j < i; j++) {
            if (i % j == 0) {
                isPrime = false;
                break;
            }
        }

        // If the number is prime, set the next prime variable to the current number
        if (isPrime) {
            nextPrime = i;
            break;
        }
    }

    // Return the next prime number
    return nextPrime;
}

public static int nextPrime(int desiredCapacity) {
    // Find the next prime number
    int prime = (desiredCapacity + 1000) / 1000; // See https://en.wikipedia.org/wiki/Hash_table#Choosing_the_size
    while (!isPrime(prime)) {
        prime += 1;
    }
    return prime;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int upperLimit = (int) (desiredCapacity * 1.1);
    int i = 3;
    while (i <= upperLimit) {
        if (isPrime(i)) {
            return i;
        }
        i += 2;
    }
    return Integer.MAX_VALUE;
}

