        return null;
    }
    int strLen = str.length();
    if (strLen == 0) {
        return "";
    }
    int lastNonWhitespace = strLen;
    for (int i = strLen - 1; i >= 0; i--) {
        if (!Character.isWhitespace(str.charAt(i))) {
            lastNonWhitespace = i + 1;
            break;
        }
    }
    return str.substring(0, lastNonWhitespace);
}

