@Override
public String readString() throws IOException {
    // Determine if the field is a String
    boolean isString = false;
    do {
        // Read a byte from the stream
        int b = in.readByte();
        // Check if the byte is less than 0
        if (b < 0) {
            // If the byte is less than 0, it means we've reached the end of the stream
            throw new EOFException();
        }
        // Check if the byte is a null byte
        if (b == 0) {
            // If the byte is a null byte, it means the field is a String
            isString = true;
            break;
        }
        // If the byte is not a null byte, it must be a UTF-8 encoded character
        // Read the UTF-8 encoded character
        char c = (char) (b & 0xFF);
        // Check if the character is a space character
        if (Character.isWhitespace(c)) {
            // If the character is a space character, it means we've reached the end of the String
            break;
        }
        // If the character is not a space character, continue reading the String
    } while (true);

    // If the field was a String, read the String from the stream
    if (isString) {
        // Create a new StringBuilder to hold the String
        StringBuilder sb = new StringBuilder();
        // Read the characters from the stream until we reach the end of the String
        while (true) {
            // Read a byte from the stream
            int b = in.readByte();
            // Check if the byte is less than 0
            if (b < 0) {
                // If the byte is less than 0, it means we've reached the end of the stream
                throw new EOFException();
            }
            // Check if the byte is a null byte
            if (b == 0) {
                // If the byte is a null byte, it means we've reached the end of the String
                break;
            }
            // If the byte is not a null byte, it must be a UTF-8 encoded character
            char c = (char) (b & 0xFF);
            // Add the character to the StringBuilder
            sb.append(c);
        }
        // Return the String
        return sb.toString();
    } else {
        // If the field was not a String, read the bytes and return them as a byte array
        byte[] bytes = new byte[0];
        do {
            // Read a byte from the stream
            int b = in.readByte();
            // Check if the byte is less than 0
            if (b < 0) {
                // If the byte is less than 0, it means we've reached the end of the stream
                break;
            }
            // Check if the byte is a null byte
            if (b == 0) {
                // If the byte is a null byte, it means we've reached the end of the byte array
                break;
            }
            // If the byte is not a null byte, it must be a byte in the byte array
            // Add the byte to the byte array
            bytes = Arrays.copyOf(bytes, bytes.length + 1);
            bytes[bytes.length - 1] = (byte) (b & 0xFF);
        } while (true);
        return bytes;
    }
