public byte[] toByteArray() {
    // Step 1: Get the length of the byte array to be returned
    int length = 0;
    for (ByteArrayOutputStream stream : streams) {
        length += stream.size();
    }

    // Step 2: Allocate a single byte array to hold all the contents of the buffer(s)
    byte[] result = new byte[length];

    // Step 3: Copy the contents of each buffer to the returned array
    int offset = 0;
    for (ByteArrayOutputStream stream : streams) {
        System.arraycopy(stream.toByteArray(), 0, result, offset, stream.size());
        offset += stream.size();
    }

    return result;
}

public final byte[] toByteArray() {
    // Create a new byte array to hold the contents of the buffers
    byte[] bytes = new byte[size];

    // Copy the contents of the buffers into the byte array
    int offset = 0;
    for (Buffer buffer : buffers) {
        System.arraycopy(buffer.array(), buffer.arrayOffset(), bytes, offset, buffer.limit() - buffer.position());
        offset += buffer.limit() - buffer.position();
    }

    return bytes;
}

public static byte[] toByteArray() {
    byte[] result = new byte[0];
    for (Buffer buffer : buffers) {
        result = Arrays.copyOf(result, result.length + buffer.size());
        System.arraycopy(buffer.toByteArray(), 0, result, result.length - buffer.size(), buffer.size());
    }
    return result;
}

public byte[] toByteArray() {
    // Keep track of the total number of bytes written
    int totalBytesWritten = 0;

    // Create a temporary array to hold the contents of the buffer
    byte[] bufferContents = new byte[getBufferSize()];

    // Write the contents of the buffer to the temporary array
    for (byte[] buffer : buffers) {
      System.arraycopy(buffer, 0, bufferContents, totalBytesWritten, buffer.length);
      totalBytesWritten += buffer.length;
    }

    // Create a new byte array to hold the concatenated contents of all the buffers
    byte[] allBufferContents = new byte[totalBytesWritten];

    // Copy the contents of the temporary array to the new byte array
    System.arraycopy(bufferContents, 0, allBufferContents, 0, totalBytesWritten);

    // Return the concatenated byte array
    return allBufferContents;
  }

public byte[] toByteArray() {
    // Create a byte array to hold the contents of the buffer(s)
    byte[] output = new byte[size()];

    // Copy the contents of the buffer(s) to the output byte array
    int pos = 0;
    for (ByteBuffer buffer : buffers) {
        System.arraycopy(buffer.array(), buffer.position(), output, pos, buffer.remaining());
        pos += buffer.remaining();
    }

    return output;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder unescapedString = new StringBuilder();
    boolean escaped = false;
    for (int i = 0; i < str.length(); i++) {
        char currentChar = str.charAt(i);
        if (escaped) {
            // Check for valid escape sequence
            if (currentChar == 'n') {
                unescapedString.append('\n');
            } else if (currentChar == 't') {
                unescapedString.append('\t');
            } else {
                unescapedString.append(currentChar);
            }
            escaped = false;
        } else if (currentChar == '\\') {
            escaped = true;
        } else {
            unescapedString.append(currentChar);
        }
    }
    return unescapedString.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    // Initialize a string builder to store the unescaped string
    StringBuilder builder = new StringBuilder();

    // Iterate through the characters in the input string
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        // If the current character is a backslash, check if the next character is also a backslash
        if (c == '\\') {
            // If the next character is a backslash, append a backslash to the string builder and skip the next character
            if (i + 1 < str.length() && str.charAt(i + 1) == '\\') {
                builder.append(c);
                i++;
            }
            // If the next character is not a backslash, append a newline character to the string builder
            else {
                builder.append('\n');
            }
        // If the current character is not a backslash, append it to the string builder
        } else {
            builder.append(c);
        }
    }

    // Return the unescaped string
    return builder.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    boolean hasChange = false;
    for (char c : str.toCharArray()) {
        if (c == '\\') {
            if (result.length() > 0 && result.charAt(result.length() - 1) == '\\') {
                // Handle escaped backslash
                result.append(c);
            } else {
                hasChange = true;
                switch (c) {
                    case 'n':
                        result.append('\n');
                        break;
                    case 'r':
                        result.append('\r');
                        break;
                    case 't':
                        result.append('\t');
                        break;
                    case 'b':
                        result.append('\b');
                        break;
                    case 'f':
                        result.append('\f');
                        break;
                    case '\\':
                        result.append('\\');
                        break;
                    default:
                        throw new Exception("Invalid escape sequence: \\" + c);
                }
            }
        } else {
            result.append(c);
        }
    }
    return hasChange ? result.toString() : str;
}

