    if (str == null) {
      return null;
    }
    StringBuilder builder = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
      char c = str.charAt(i);
      if (c == '\\') {
        builder.append(unescapeJavaChar(str, i++));
      } else {
        builder.append(c);
      }
    }
    return builder.toString();
  }

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            // Check if the backslash is escaped
            if (i + 1 < str.length() && str.charAt(i + 1) == '\\') {
                // If the backslash is escaped, add it to the string builder
                sb.append(c);
                i++;
            } else {
                // If the backslash is not escaped, check if it's followed by a valid escape sequence
                if (i + 1 < str.length() && str.charAt(i + 1) == 'n') {
                    // If the backslash is followed by 'n', add a newline character to the string builder
                    sb.append('\n');
                } else if (i + 1 < str.length() && str.charAt(i + 1) == 't') {
                    // If the backslash is followed by 't', add a tab character to the string builder
                    sb.append('\t');
                } else if (i + 1 < str.length() && str.charAt(i + 1) == 'r') {
                    // If the backslash is followed by 'r', add a carriage return character to the string builder
                    sb.append('\r');
                } else {
                    // If the backslash is not followed by a valid escape sequence, throw an exception
                    throw new Exception("Invalid escape sequence");
                }

                // Skip the next character since it has been handled
                i++;
            }
        } else {
            // If the character is not a backslash, add it to the string builder
            sb.append(c);
        }
    }

    return sb.toString();
}

