    // Read the CONSTANT_Utf8 entry from the constant pool table
    int startIndex = readUnsignedShort(constantPoolEntryIndex);
    int length = readUnsignedShort(startIndex);

    // Check if the buffer is large enough to hold the string
    if (charBuffer.length < length) {
        throw new IllegalArgumentException("Char buffer is too small");
    }

    // Read the string data from the constant pool table
    for (int i = 0; i < length; i++) {
        charBuffer[i] = (char) readUnsignedByte(startIndex + 2 + i);
    }

