        throw new IllegalArgumentException("n must be non-negative.");
    }

    long result = 1;
    for (int i = 2; i <= n; i++) {
        result *= i;
    }

    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
   if (start == null || stop == null || dir == 0) {
      return null;
   }

   OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
   Node current = circulator.next();

   while (current != stop && current != null) {
      if (predicate.test(current)) {
         return circulator;
      }

      current = circulator.next();
   }

   return null;
}

public static OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start);
    while (circulator.next() != stop) {
        Node node = circulator.getNode();
        if (predicate.test(node)) {
            return circulator;
        }
    }
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // check if the start node satisfies the predicate
    if (predicate.test(start)) {
        return new OuterFaceCirculator(start, start, start);
    }

    // check if the stop node satisfies the predicate
    if (predicate.test(stop)) {
        return new OuterFaceCirculator(stop, stop, stop);
    }

    // check if the direction is valid
    if (dir != Direction.X && dir != Direction.Y) {
        throw new IllegalArgumentException("Invalid direction: " + dir);
    }

    // initialize the circulator
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop, dir);

    // check if the circulator has a next node that satisfies the predicate
    while (circulator.hasNext()) {
        Node node = circulator.next();
        if (predicate.test(node)) {
            return circulator;
        }
    }

    // if no node satisfies the predicate, return the circulator to the stop node
    return new OuterFaceCirculator(stop, stop, stop);
}

