    int[] shardingKeyIndices = getShardingKeyIndices(modelName);
    if (shardingKeyIndices == null || shardingKeyIndices.length == 0) {
        throw new IllegalStateException("Sharding key indices are not defined for " + modelName + ".");
    }
    int lastKeyIndex = shardingKeyIndices[0];
    for (int i = 1; i < shardingKeyIndices.length; i++) {
        if (shardingKeyIndices[i] - lastKeyIndex != 1) {
            throw new IllegalStateException("Sharding key indices are not continuous for " + modelName + ".");
        }
        lastKeyIndex = shardingKeyIndices[i];
    }
}

public void check(String modelName) throws IllegalStateException {
    // Step 1: Check for null and empty model name
    if (modelName == null || modelName.isEmpty()) {
        throw new IllegalArgumentException("Model name cannot be null or empty");
    }

    // Step 2: Split the model name into individual words
    String[] modelNameWords = modelName.split(" ");

    // Step 3: Create a map to store the sharding key indices
    Map<Integer, Integer> shardingKeyIndices = new HashMap<>();

    // Step 4: Iterate through the model name words and check for sharding keys
    for (int i = 0; i < modelNameWords.length; i++) {
        // Check if the word is a sharding key
        if (modelNameWords[i].startsWith("sharding_key(") && modelNameWords[i].endsWith(")")) {
            // Get the index of the sharding key from the word
            int shardingKeyIndex = Integer.parseInt(modelNameWords[i].substring(13, modelNameWords[i].length() - 1));

            // Check if the sharding key index is in the map
            if (shardingKeyIndices.containsKey(shardingKeyIndex)) {
                // Throw an IllegalStateException if the sharding key index is not continuous
                throw new IllegalStateException("Sharding key indices are not continuous");
            }

            // Add the sharding key index to the map
            shardingKeyIndices.put(shardingKeyIndex, i);
        }
    }

    // Step 5: Check if the sharding key indices are continuous
    List<Integer> shardingKeyIndicesList = new ArrayList<>(shardingKeyIndices.keySet());
    Collections.sort(shardingKeyIndicesList);
    for (int i = 0; i < shardingKeyIndicesList.size() - 1; i++) {
        if (shardingKeyIndicesList.get(i) + 1 != shardingKeyIndicesList.get(i + 1)) {
            throw new IllegalStateException("Sharding key indices are not continuous");
        }
    }
}

