protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // handle invalid input
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph cannot be null");
    }

    // create an empty graph path
    GraphPath<V, E> path = new GraphPath<>(graph);

    // iterate over the edges in the tour set
    for (E edge : tour) {
        // get the source and target vertices of the edge
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        // add a new edge and vertex to the graph path
        path.addEdge(graph.findVertex(source), graph.findVertex(target));
    }

    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Initialize the GraphPath with the given graph
    GraphPath<V,E> path = new GraphPath<V,E>(graph);

    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Add the edge to the path
        path.append(edge);

        // Look up the adjacent nodes of the edge
        V node1 = graph.getEdgeSource(edge);
        V node2 = graph.getEdgeTarget(edge);

        // Add the adjacent nodes to the path
        path.append(node1);
        path.append(node2);
    }

    // Return the generated path
    return path;
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Step 1: Validate input
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    // Step 2: Create a new GraphPath
    GraphPath<V, E> tourPath = graph.createPath();

    // Step 3: Add edges to the GraphPath
    for (E edge : tour) {
        if (graph.containsEdge(edge)) {
            tourPath.addEdge(edge);
        } else {
            throw new IllegalArgumentException("Edge " + edge + " is not in the graph");
        }
    }

    return tourPath;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Null input not allowed.");
    }

    VertexList<V> vertexList = new VertexList<>();
    for (E edge : tour) {
        Vertex<V> sourceVertex = graph.getEdgeSource(edge);
        Vertex<V> targetVertex = graph.getEdgeTarget(edge);
        if (sourceVertex == null || targetVertex == null) {
            throw new IllegalArgumentException("Invalid edge: " + edge);
        }
        vertexList.add(sourceVertex);
        vertexList.add(targetVertex);
    }

    return new GraphPath<>(vertexList);
}

public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Step 1: Check that the input parameters are valid
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    // Step 2: Create an empty graph path
    GraphPath<V, E> path = new GraphPath<>(graph);

    // Step 3: Iterate over the edges in the tour and add them to the graph path
    for (E edge : tour) {
        if (edge == null) {
            throw new IllegalArgumentException("Null edge found in tour");
        }
        path = path.addEdge(edge);
    }

    // Step 4: Return the completed graph path
    return path;
}

