public int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new java.lang.IllegalArgumentException("Name and descriptor must not be null");
    }

    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPool.size(); i++) {
        ConstantInfo constant = constantPool.get(i);
        if (constant instanceof ConstantNameAndTypeInfo) {
            ConstantNameAndTypeInfo nameAndTypeInfo = (ConstantNameAndTypeInfo) constant;
            if (nameAndTypeInfo.getName().equals(name) && nameAndTypeInfo.getDescriptor().equals(descriptor)) {
                return i;
            }
        }
    }

    // If we reached this point, the constant pool does not contain a similar item, so we create a new one
    ConstantNameAndTypeInfo nameAndTypeInfo = new ConstantNameAndTypeInfo(name, descriptor);
    constantPool.add(nameAndTypeInfo);
    return constantPool.size() - 1;
}

private static Symbol addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("name and descriptor cannot be null");
    }

    // check if the constant pool already contains a similar item
    for (Symbol symbol : constantPool) {
        if (symbol.getName().equals(name) && symbol.getDescriptor().equals(descriptor)) {
            // the constant pool already contains a similar item, return it
            return symbol;
        }
    }

    // create a new Symbol and add it to the constant pool
    Symbol newSymbol = new Symbol(name, descriptor);
    constantPool.add(newSymbol);

    return newSymbol;
}

public int addConstantNameAndType(String name, String descriptor) {
    // Step 1: Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPool.size(); i++) {
        ConstantPoolItem item = constantPool.get(i);
        if (item instanceof ConstantPoolItemNameAndType && item.getName().equals(name) && item.getDescriptor().equals(descriptor)) {
            return i;
        }
    }

    // Step 2: Create a new ConstantPoolItemNameAndType and add it to the constant pool
    ConstantPoolItemNameAndType item = new ConstantPoolItemNameAndType(name, descriptor);
    constantPool.add(item);

    // Step 3: Return the index of the new item in the constant pool
    return constantPool.size() - 1;
}

