    if (input.contains("\\")) {
        try {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < input.length(); i++) {
                char c = input.charAt(i);
                if (c == '\\') {
                    // Unescape the next character
                    c = input.charAt(++i);
                    switch (c) {
                        case 'b':
                            sb.append('\b');
