  // Verify that the input is valid
  if (bucketsByLabel == null || labels == null || minLabel < 0)
    throw new IllegalArgumentException("The input is invalid");

  // Verify that the minimum label is not equal to the maximum label
  if (minLabel == labels.get(0))
    throw new IllegalArgumentException("The minimum label is not valid");

  // Move all vertices from the bucket with the minimum label to the bucket with label 0
  for (Integer vertex : bucketsByLabel.get(minLabel)) {
    bucketsByLabel.get(0).add(vertex);
  }

  // Clear the bucket with the minimum label
  bucketsByLabel.set(minLabel, new HashSet<Integer>());

