    }
  }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Check if the given labels are valid
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid minLabel provided: " + minLabel);
    }

    // Get the bucket with minimum label
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    if (minBucket.isEmpty()) {
        throw new IllegalStateException("No vertices in bucket with label " + minLabel);
    }

    // Move all vertices from the minimum label bucket to bucket 0
    for (int v : minBucket) {
        bucketsByLabel.get(0).add(v);
        labels.set(v, 0);
    }

    // Clear the minimum label bucket
    minBucket.clear();
}

