private String parseToken(final char[] terminators) throws IllegalArgumentException {
    // Validate input
    if (terminators == null || terminators.length == 0) {
        throw new IllegalArgumentException("No terminators provided");
    }

    String token = "";
    boolean terminated = false;

    // Read characters until the first terminator is encountered
    while (!terminated && this.hasNext()) {
        char c = this.next();
        terminated = Arrays.binarySearch(terminators, c) >= 0;
        if (!terminated) {
            token += c;
        }
    }

    return token;
}

