public <Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    //Initialize the list of suffix sums with the first element of bounds.
    List<Integer> suffixSum = new ArrayList<Integer>();
    suffixSum.add(bounds.get(0));
    long sum = bounds.get(0);

    //Iterate through the remaining elements of bounds, from the beginning when the length is greater than 0 to one before the end, and for each 
    //element, calculate the sum of the element and the element that immediately follows it, and 
    //add this sum to the sum of all elements and the list of sum values.
    for (int i = 0; i < bounds.size()-1; i++) {
        sum += bounds.get(i+1);
        suffixSum.add(sum);
    }

    //Return the list of sum values and the sum of all elements.
    return new Pair<Long, List<Integer>>(sum, suffixSum);
}

public static Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize the list to store the suffix sum
    List<Integer> suffixSum = new ArrayList<>();

    // Initialize the sum of all elements
    long totalSum = 0L;

    // Loop through the list of bounds and compute the suffix sum
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Compute the current sum and add it to the total sum
        long currentSum = 0L;
        for (int j = i; j < bounds.size(); j++) {
            currentSum += bounds.get(j);
        }
        totalSum += currentSum;

        // Add the current sum to the list of suffix sums
        suffixSum.add((int) currentSum);
    }

    // Return the computed suffix sum and the total sum
