private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Get the head of the list to move
    ListNode<E> headToMove = list.getHead();

    // Move the head of the list to this list
    addListNode(headToMove);

    // Move all the other nodes of the list to this list
    ListNode<E> current = headToMove.getNext();
    while (current != null) {
        // Get the next node to move
        ListNode<E> nextToMove = current.getNext();

        // Remove the current node from the list
        removeListNode(current);

        // Add the current node to this list
        addListNode(current);

        // Move to the next node
        current = nextToMove;
    }
}

