    if (intValue < -128 || intValue > 127) {
        throw new IllegalArgumentException("The int value is out of range");
    }

    // Step 2: Convert the int to a byte array
    byte[] bytes = new byte[4];
    bytes[0] = (byte) ((intValue >> 24) & 0xff);
    bytes[1] = (byte) ((intValue >> 16) & 0xff);
    bytes[2] = (byte) ((intValue >> 8) & 0xff);
    bytes[3] = (byte) (intValue & 0xff);

    // Step 3: Enlarge the byte vector if necessary
    final int newSize = offset + bytes.length;
    if (newSize > data.length) {
        data = Arrays.copyOf(data, Math.max(data.length * 2, newSize));
    }

    // Step 4: Append the byte array to the byte vector
    System.arraycopy(bytes, 0, data, offset, bytes.length);
    offset += bytes.length;

    // Step 5: Return this byte vector
    return this;
}

