public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the given vertices are all vertices in the graph
    if (!graph.getVertices().containsAll(vertices)) {
        throw new IllegalArgumentException("The given vertices are not all vertices in the graph");
    }

    // Check if the given vertices can form a complete subgraph
    if (vertices.size() < 2) {
        return false;
    }

    // Check if all possible pairs of vertices in the given set are adjacent
    for (int i = 0; i < vertices.size(); i++) {
        for (int j = i + 1; j < vertices.size(); j++) {
            V vertex1 = vertices.get(i);
            V vertex2 = vertices.get(j);
            if (!graph.isAdjacent(vertex1, vertex2)) {
                return false;
            }
        }
    }

    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Check if the subgraph is not empty and the number of vertices is equal to the number of edges
    if (vertices.size() == 0 || vertices.size() != graph.edgeSet().size()) {
        return false;
    }

    // Create a new graph based on the subgraph induced by the given vertices
    Graph<V, E> subgraph = Graphs.induceSubgraph(graph, vertices);

    // Check if the subgraph is connected
    if (subgraph.isConnected()) {
        // Check if the subgraph is a clique, i.e. has the property that every vertex is connected to every other vertex
        // This can be done by checking if every vertex is a neighbor of every other vertex
        for (V v1 : subgraph.vertexSet()) {
            for (V v2 : subgraph.vertexSet()) {
                if (!subgraph.containsEdge(v1, v2)) {
                    return false;
                }
            }
        }
        return true;
    }
    return false;
}

