    // Check if all the vertices are present in the graph
    if (!vertices.stream().allMatch(graph::containsVertex)) {
        throw new IllegalArgumentException("The given vertices are not all present in the graph.");
    }

    // Check if all the vertices are connected to each other
    for (int i = 0; i < vertices.size(); i++) {
        V vertex1 = vertices.get(i);
        for (int j = i + 1; j < vertices.size(); j++) {
            V vertex2 = vertices.get(j);
            if (!graph.containsEdge(vertex1, vertex2)) {
