    if (vertices.size() < 2) {
        return false;
    }

    // Check if the given vertices cover all the vertices in the graph
    if (!graph.vertexSet().containsAll(vertices)) {
        return false;
    }

    // Check if the given vertices are connected by an edge
    for (V u : vertices) {
        for (V v : vertices) {
            if (u.equals(v)) {
                continue;
            }
            if (!graph.containsEdge(u, v)) {
                return false;
            }
        }
    }

    return true;
}

