    // Define the type and sizes of the types to be popped
    Class<?>[] types = null;
    int[] sizes = null;
    if (descriptor.startsWith("(")) {
        types = new Class<?>[descriptor.length() - 2];
        sizes = new int[descriptor.length() - 2];
        for (int i = 1; i < descriptor.length() - 1; i++) {
            if (descriptor.charAt(i) == ')') {
                types[i - 1] = void.class;
                sizes[i - 1] = 0;
            } else {
                types[i - 1] = Class.forName(descriptor.substring(i, i + 1));
                sizes[i - 1] = types[i - 1].getSize();
            }
        }
    } else {
        types = new Class<?>[1];
        sizes = new int[1];
        types[0] = Class.forName(descriptor);
        sizes[0] = types[0].getSize();
    }

    // Pop the corresponding number of frames from the output frame stack
    int frameCount = 0;
    while (frameCount < sizes.length) {
        Frame frame = outputFrameStack.pop();
        if (frame.getSize() != sizes[frameCount]) {
            throw new IllegalStateException("The output frame stack contains a frame with an incorrect size");
        }
        frameCount++;
    }
}

