private void pop(String descriptor) {
    if (framework.outputFrame.isEmpty()) {
        throw new IllegalStateException("No more objects to pop from the stack");
    }
    Type type = Type.getType(descriptor);
    if (type.getSort() != Type.OBJECT) {
        throw new UnsupportedOperationException("Cannot pop a type that is not an object");
    }
    String internalName = type.getInternalName();
    if (internalName.indexOf('<') >= 0) {
        internalName = Type.getType(internalName).getInternalName();
    }
    int count = getCountToPop(internalName);
    for (int i = 0; i < count; i++) {
        InstructionHandle ih = framework.outputFrame.pop();
        framework.getTarget().accept(ih);
    }
}

