public static String applyRelativePath(String path, String relativePath) {
    int lastSeparatorIndex = path.lastIndexOf('/');
    if (lastSeparatorIndex == -1) {
        return relativePath;
    }
    String basePath = path.substring(0, lastSeparatorIndex + 1);
    return basePath + relativePath;
}

public static String applyRelativePath(String path, String relativePath) {
    // Check for null or empty input
    if (path == null || path.isEmpty() || relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Split the path and relative path into their component parts
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    // Initialize the result array with the first part of the path
    String[] resultParts = new String[pathParts.length];
    resultParts[0] = pathParts[0];

    // Iterate over the relative path parts and apply them to the result
    for (int i = 1; i < relativePathParts.length; i++) {
        // If the current part is "..", remove the last entry from the result
        if (relativePathParts[i].equals("..")) {
            if (resultParts.length > 1) {
                resultParts = Arrays.copyOf(resultParts, resultParts.length - 1);
            } else {
                throw new IllegalArgumentException("Tried to remove too many directories");
            }
        } else {
            // Otherwise, add the part to the result
            resultParts = Arrays.copyOf(resultParts, resultParts.length + 1);
            resultParts[resultParts.length - 1] = relativePathParts[i];
        }
    }

    // Join the result parts into a single path string
    String result = String.join("/", resultParts);

    // Return the resulting path
    return result;
}

public static String applyRelativePath(String path, String relativePath) {
    // Check for null or empty inputs
    if (path == null || path.isEmpty() || relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Inputs cannot be null or empty");
    }

    // Remove any leading or trailing slashes from the input paths
    path = path.trim();
    relativePath = relativePath.trim();

    // If the relative path is already absolute, return it as is
    if (relativePath.startsWith("/")) {
        return relativePath;
    }

    // If the path is already absolute, remove the file name from the end
    if (path.endsWith("/")) {
        path = path.substring(0, path.lastIndexOf('/'));
    } else {
        path = path.substring(0, path.lastIndexOf('/') + 1);
    }

    // Append the relative path to the end of the path
    return path + relativePath;
}

public static String applyRelativePath(String path, String relativePath) {
    // Split the path and relative path into separate components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Create a new array list to store the combined path components
    List<String> combinedPathComponents = new ArrayList<>();

    // Loop through the path components and add them to the combined list,
    // unless they are empty strings or "."
    for (String component : pathComponents) {
        if (!component.isEmpty() && !".".equals(component)) {
            combinedPathComponents.add(component);
        }
    }

    // Loop through the relative path components and add them to the combined list,
    // unless they are empty strings or ".."
    for (String component : relativePathComponents) {
        if (!component.isEmpty() && !"..".equals(component)) {
            combinedPathComponents.add(component);
        } else if ("..".equals(component)) {
            // If we encounter a "..", remove the last component from the combined list
            if (!combinedPathComponents.isEmpty()) {
                combinedPathComponents.remove(combinedPathComponents.size() - 1);
            }
        }
    }

    // Join the combined path components into a single string, separated by "/"
    String combinedPath = String.join("/", combinedPathComponents);

    // Return the combined path
    return combinedPath;
}

public static String applyRelativePath(String path, String relativePath) {
    // Validate input
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Input arguments can't be null");
    }

    // Split the path into its individual components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Build the resulting path by appending the relative path components to the end of the path
    StringBuilder result = new StringBuilder();
    for (String component : pathComponents) {
        result.append(component).append("/");
    }
    for (String component : relativePathComponents) {
        result.append(component).append("/");
    }

    // Remove any trailing slashes
    if (result.length() > 0 && result.charAt(result.length() - 1) == '/') {
        result.deleteCharAt(result.length() - 1);
    }

    return result.toString();
}

