    if (extensionSeparatorIndex != -1) {
        int nextSeparatorIndex = indexOfNextSeparator(filename, extensionSeparatorIndex);
        if (nextSeparatorIndex == -1 || nextSeparatorIndex > lastSeparatorIndex) {
