    // Step 1: Get the connected clients from the client registry
    List<Client> clients = ClientRegistry.getInstance().getClients();

    // Step 2: Iterate over the clients and write the message to each one
    for (Client client : clients) {
        try {
            // Step 3: Get the output stream from the client
            OutputStream outputStream = client.getOutputStream();

            // Step 4: Create a writer for the output stream
            PrintWriter writer = new PrintWriter(outputStream);

            // Step 5: Write the log event message to the writer
            writer.println(event.getMessage());

            // Step 6: Flush the writer to ensure the message is sent to the client
            writer.flush();

            // Step 7: Close the writer to release system resources
            writer.close();
        } catch (IOException e) {
            // Step 8: If an exception is thrown, remove the client from the registry
            System.out.println("Error writing to client: " + e.getMessage());
            ClientRegistry.getInstance().removeClient(client);
        }
    }
}

