public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Set up the output list
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    // Open the file for reading
    FileInputStream fileInputStream = new FileInputStream(file);
    BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(fileInputStream));

    // Iterate through the time ranges
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        // Set up the time range parameters
        int startTime = timeRange.getStartTime();
        int endTime = timeRange.getEndTime();

        // Iterate through the file lines, checking for the relevant data
        String line;
        while ((line = bufferedReader.readLine()) != null) {
            // Check if the line contains the thread snapshot data
            if (line.contains("ThreadSnapshot")) {
                // Extract the thread snapshot data
                JSONObject snapshotJson = new JSONObject(line);
                String threadName = snapshotJson.getString("thread_name");
                int threadStartTime = snapshotJson.getInt("thread_start_time");
                int threadEndTime = snapshotJson.getInt("thread_end_time");

                // Check if the thread snapshot is within the specified time range
                if (threadStartTime >= startTime && threadStartTime <= endTime) {
                    // Add the thread snapshot to the output list
                    threadSnapshots.add(new ThreadSnapshot(threadName, threadStartTime, threadEndTime));
                }
            }
        }
    }

    // Close the file
    bufferedReader.close();
    fileInputStream.close();

    // Return the output list
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    if (file == null || timeRanges == null || timeRanges.isEmpty()) {
        return threadSnapshots;
    }
    String fileContent = readFileAsString(file);
    if (fileContent == null || fileContent.isEmpty()) {
        return threadSnapshots;
    }
    // Split the file content by line
    String[] fileLines = fileContent.split("\n");
    // Iterate over the file lines
    for (String line : fileLines) {
        // Skip empty lines
        if (line.trim().isEmpty()) {
            continue;
        }
        // Check if the line is a time range
        if (line.matches(".*\\d\\s*:\\s*\\d\\d\\d\\d")) {
            // Extract the time range from the line
            String[] timeRangeParts = line.split("\\s*:\\s*");
            long startTimeInNanos = ChronoUnit.MILLIS.toNanos(Long.parseLong(timeRangeParts[0]));
            long endTimeInNanos = ChronoUnit.MILLIS.toNanos(Long.parseLong(timeRangeParts[1]));
            // Filter the time ranges based on the input
            List<ProfileAnalyzeTimeRange> filteredTimeRanges = timeRanges.stream()
                    .filter(tr -> tr.getStartTimeInNanos() <= startTimeInNanos && tr.getEndTimeInNanos() >= endTimeInNanos)
                    .collect(Collectors.toList());
            if (filteredTimeRanges.isEmpty()) {
                continue;
            }
            // Parse the thread snapshot from the line
            ThreadSnapshot threadSnapshot = parseThreadSnapshotFromLine(line, filteredTimeRanges.get(0));
            // Add the thread snapshot to the result
            threadSnapshots.add(threadSnapshot);
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    Args.notNull(file, "file");
    Args.notNull(timeRanges, "timeRanges");

    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] fields = line.split(",");
            if (fields.length < 3) {
                continue;
            }

            long timestamp = Long.parseLong(fields[0]);
            long startTime = Long.parseLong(fields[1]);
            long endTime = Long.parseLong(fields[2]);

            if (timeRanges.stream().anyMatch(timeRange -> timeRange.contains(timestamp))) {
                threadSnapshots.add(new ThreadSnapshot(timestamp, startTime, endTime));
            }
        }
    }

    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Check if the file exists
    if (!file.exists()) {
        throw new FileNotFoundException("File does not exist");
    }

    // Check if the time ranges are valid
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Invalid time ranges");
    }

    // Read the file content
    List<String> lines = Files.readAllLines(file.toPath(), StandardCharsets.UTF_8);

    // Create a map to store the thread snapshots by thread name
    Map<String, ThreadSnapshot> threadSnapshotsMap = new HashMap<>();

    // Iterate over the file content and add the thread snapshots to the map
    for (String line : lines) {
        // Skip empty lines and lines that are not starting with "ThreadSnapshot"
        if (line.trim().isEmpty() || !line.startsWith("ThreadSnapshot")) {
            continue;
        }

        // Parse the thread snapshot information
        ThreadSnapshot threadSnapshot = parseThreadSnapshot(line);

        // Check if the thread snapshot is within the time range
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (timeRange.getStartTime() <= threadSnapshot.getTimestamp() && threadSnapshot.getTimestamp() <= timeRange.getEndTime()) {
                // Add the thread snapshot to the map
                threadSnapshotsMap.put(threadSnapshot.getThreadName(), threadSnapshot);
                break;
            }
        }
    }

    // Return the list of thread snapshots
    return new ArrayList<>(threadSnapshotsMap.values());
}

private static List<ThreadSnapshot> parseFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();

    try (FileReader reader = new FileReader(file)) {
        BufferedReader br = new BufferedReader(reader);
        String line;
        while ((line = br.readLine()) != null) {
            String[] parts = line.split(",");
            if (parts.length > 2) {
                try {
                    long threadId = Long.parseLong(parts[0]);
                    String threadName = parts[1];
                    long startTime = Long.parseLong(parts[2]);
                    long endTime = Long.parseLong(parts[3]);
                    float cpuUsage = Float.parseFloat(parts[4]);

                    ProfileAnalyzeTimeRange timeRange = getTimeRange(timeRanges, startTime, endTime);
                    if (timeRange != null) {
                        ThreadSnapshot snapshot = new ThreadSnapshot(threadId, threadName, startTime, endTime, cpuUsage);
                        timeRange.addThreadSnapshot(snapshot);
                        snapshots.add(snapshot);
                    }
                } catch (NumberFormatException e) {
                    // ignore invalid lines
                }
            }
        }
    }

    return snapshots;
}

private static ProfileAnalyzeTimeRange getTimeRange(List<ProfileAnalyzeTimeRange> timeRanges, long startTime, long endTime) {
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (timeRange.getStartMs() <= startTime && timeRange.getEndMs() >= endTime) {
            return timeRange;
        }
    }

    return null;
}
